def min_val(listval):
    """Write a function to find the minimum value in a given heterogeneous list.

    Non-numeric elements (such as strings) are ignored. Returns ``None``
    when the list contains no numeric values.
    """
    numeric_values = [
        value for value in listval if isinstance(value, (int, float))
    ]
    if not numeric_values:
        return None
    return min(numeric_values)
